from __future__ import annotations

import json
from typing import Any

from fastmcp import Client
from fastmcp.client.transports import StreamableHttpTransport
from langflow.custom import Component
from langflow.io import (
    DataInput,
    IntInput,
    MessageTextInput,
    Output,
    SecretStrInput,
    StrInput,
)
from langflow.schema import Message


class DirectIntugleMCPCaller(Component):
    display_name = "Direct Intugle MCP Caller"
    description = (
        "Calls IntugleAgent directly using a persistent session ID "
        "and returns the response for downstream processing."
    )
    icon = "Bot"
    name = "DirectIntugleMCPCaller"

    inputs = [
        DataInput(
            name="email_data",
            display_name="Current Email",
            required=True,
        ),
        MessageTextInput(
            name="session_id",
            display_name="Session ID",
            required=True,
        ),
        StrInput(
            name="mcp_url",
            display_name="MCP URL",
            value="https://app.intugle.ai/mcp",
            required=True,
        ),
        SecretStrInput(
            name="mcp_api_key",
            display_name="MCP API Key",
            required=True,
        ),
        StrInput(
            name="extra_params",
            display_name="x-extra-params",
            value="",
            required=False,
            advanced=True,
        ),
        IntInput(
            name="timeout",
            display_name="Timeout Seconds",
            value=300,
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="evidence",
            display_name="Intugle Evidence",
            method="call_intugle",
        ),
    ]

    async def call_intugle(self) -> Message:
        raw_result, answer = await self._get_result()

        if self._is_error(raw_result):
            raise ValueError(
                answer
                or "IntugleAgent returned an MCP tool error."
            )

        if not answer:
            raise ValueError(
                "IntugleAgent returned an empty response."
            )

        return Message(
            text=answer,
            sender="Machine",
            sender_name="IntugleAgent",
        )

    async def _get_result(
        self,
    ) -> tuple[dict[str, Any], str]:

        question = self._normalise_email_data(
            self.email_data
        )

        if not question:
            raise ValueError(
                "Current Email cannot be empty."
            )

        session_id = self._normalise_text(
            self.session_id
        )

        if not session_id:
            raise ValueError(
                "Session ID cannot be empty."
            )

        mcp_url = str(
            self.mcp_url or ""
        ).strip()

        if not mcp_url:
            raise ValueError(
                "MCP URL is required."
            )

        api_key = self._normalise_secret(
            self.mcp_api_key
        )

        if not api_key:
            raise ValueError(
                "MCP API key is required."
            )

        extra_params = str(
            self.extra_params or ""
        ).strip()

        cache_key = (
            question,
            session_id,
            mcp_url,
            extra_params,
            int(self.timeout),
        )

        if (
            getattr(
                self,
                "_cached_request_key",
                None,
            )
            == cache_key
            and hasattr(
                self,
                "_cached_raw_result",
            )
        ):
            return (
                self._cached_raw_result,
                self._cached_answer,
            )

        headers: dict[str, str] = {
            "Authorization": f"Bearer {api_key}",
            "x-session-id": session_id,
        }

        if (
            extra_params
            and extra_params != "{}"
        ):
            try:
                parsed_extra_params = json.loads(
                    extra_params
                )

            except json.JSONDecodeError as exc:
                raise ValueError(
                    "x-extra-params must be valid JSON."
                ) from exc

            if parsed_extra_params:
                headers[
                    "x-extra-params"
                ] = json.dumps(
                    parsed_extra_params,
                    ensure_ascii=False,
                    separators=(",", ":"),
                )

        transport = StreamableHttpTransport(
            url=mcp_url,
            headers=headers,
        )

        try:
            async with Client(
                transport,
                auto_initialize=False,
                timeout=float(
                    self.timeout
                ),
            ) as client:

                await client.initialize(
                    timeout=float(
                        self.timeout
                    )
                )

                result = await client.call_tool_mcp(
                    "IntugleAgent",
                    {
                        "question": question,
                    },
                    timeout=float(
                        self.timeout
                    ),
                )

        except Exception as exc:
            raise ValueError(
                f"Failed to call IntugleAgent: {exc}"
            ) from exc

        raw_result = self._to_dict(
            result
        )

        answer = self._extract_exact_text(
            raw_result
        )

        self._cached_request_key = cache_key
        self._cached_raw_result = raw_result
        self._cached_answer = answer

        return (
            raw_result,
            answer,
        )

    @staticmethod
    def _is_error(
        raw_result: dict[str, Any],
    ) -> bool:
        return bool(
            raw_result.get(
                "isError",
                raw_result.get(
                    "is_error",
                    False,
                ),
            )
        )

    @staticmethod
    def _normalise_email_data(
        value: Any,
    ) -> str:

        if value is None:
            return ""

        # Langflow Data object
        if hasattr(value, "data"):
            try:
                value = value.data
            except Exception:
                pass

        # JSON string fallback
        if isinstance(value, str):
            raw = value.strip()

            if not raw:
                return ""

            try:
                parsed = json.loads(raw)

                if isinstance(parsed, dict):
                    value = parsed
                else:
                    return raw

            except json.JSONDecodeError:
                return raw

        if not isinstance(value, dict):
            raise ValueError(
                "Current Email must be a Data/JSON object."
            )

        # Handle Langflow Data wrapper if present
        nested_data = value.get("data")

        if isinstance(nested_data, dict):
            value = nested_data

        sender_email = str(
            value.get("sender_email") or ""
        ).strip()

        sender_name = str(
            value.get("sender_name") or ""
        ).strip()

        subject = str(
            value.get("subject") or ""
        ).strip()

        body_text = str(
            value.get("body_text") or ""
        ).strip()

        if not body_text:
            raise ValueError(
                "Current Email body_text is empty."
            )

        lines = []

        # Keep sender identity because Intugle may need it
        # for customer/account verification.
        if sender_name and sender_email:
            lines.append(
                f"From: {sender_name} <{sender_email}>"
            )

        elif sender_email:
            lines.append(
                f"From: {sender_email}"
            )

        elif sender_name:
            lines.append(
                f"From: {sender_name}"
            )

        # Only include subject when one actually exists.
        if subject:
            lines.append(
                f"Subject: {subject}"
            )

        # Separate metadata from actual customer content.
        if lines:
            lines.append("")

        lines.append(body_text)

        return "\n".join(lines).strip()

    @staticmethod
    def _normalise_text(
        value: Any,
    ) -> str:

        if isinstance(
            value,
            Message,
        ):
            return str(
                value.text or ""
            ).strip()

        if hasattr(
            value,
            "text",
        ):
            return str(
                value.text or ""
            ).strip()

        return str(
            value or ""
        ).strip()

    @staticmethod
    def _normalise_secret(
        value: Any,
    ) -> str:

        if value is None:
            return ""

        if hasattr(
            value,
            "get_secret_value",
        ):
            return str(
                value.get_secret_value()
                or ""
            ).strip()

        return str(
            value or ""
        ).strip()

    def _extract_exact_text(
        self,
        raw_result: dict[str, Any],
    ) -> str:

        structured = (
            raw_result.get(
                "structuredContent"
            )
            or raw_result.get(
                "structured_content"
            )
        )

        if isinstance(
            structured,
            dict,
        ):
            structured_result = structured.get(
                "result"
            )

            text = self._render_value(
                structured_result
            )

            if text:
                return text

        content = raw_result.get(
            "content"
        ) or []

        if isinstance(
            content,
            list,
        ):
            parts: list[str] = []

            for item in content:
                if not isinstance(
                    item,
                    dict,
                ):
                    continue

                text = item.get(
                    "text"
                )

                if (
                    isinstance(
                        text,
                        str,
                    )
                    and text.strip()
                ):
                    parts.append(
                        self._unwrap_json_text(
                            text
                        )
                    )

                    continue

                item_content = item.get(
                    "content"
                )

                if (
                    item_content
                    is not None
                ):
                    rendered = self._render_value(
                        item_content
                    )

                    if rendered:
                        parts.append(
                            rendered
                        )

            if parts:
                return "\n\n".join(
                    part
                    for part in parts
                    if part
                ).strip()

        return self._render_value(
            content
        )

    def _render_value(
        self,
        value: Any,
    ) -> str:

        if value is None:
            return ""

        if isinstance(
            value,
            str,
        ):
            return self._unwrap_json_text(
                value
            )

        if isinstance(
            value,
            list,
        ):
            parts = [
                self._render_value(
                    item
                )
                for item in value
            ]

            return "\n\n".join(
                part
                for part in parts
                if part
            ).strip()

        if isinstance(
            value,
            dict,
        ):
            item_type = str(
                value.get(
                    "type"
                )
                or ""
            ).strip().lower()

            if item_type in {
                "text",
                "markdown",
            }:
                content = value.get(
                    "content"
                )

                if content is None:
                    content = value.get(
                        "text"
                    )

                return self._render_value(
                    content
                )

            if (
                value.get(
                    "text"
                )
                is not None
            ):
                return self._render_value(
                    value[
                        "text"
                    ]
                )

            if (
                value.get(
                    "content"
                )
                is not None
            ):
                return self._render_value(
                    value[
                        "content"
                    ]
                )

            if (
                value.get(
                    "result"
                )
                is not None
            ):
                return self._render_value(
                    value[
                        "result"
                    ]
                )

            return json.dumps(
                value,
                ensure_ascii=False,
            )

        return str(
            value
        ).strip()

    def _unwrap_json_text(
        self,
        value: str,
    ) -> str:

        raw = str(
            value or ""
        ).strip()

        if not raw:
            return ""

        if not raw.startswith(
            ("{", "[")
        ):
            return raw

        try:
            parsed = json.loads(
                raw
            )

        except json.JSONDecodeError:
            return raw

        return self._render_value(
            parsed
        )

    @classmethod
    def _to_dict(
        cls,
        result: Any,
    ) -> dict[str, Any]:

        if isinstance(
            result,
            dict,
        ):
            return cls._dump_value(
                result
            )

        if hasattr(
            result,
            "model_dump",
        ):
            try:
                return result.model_dump(
                    by_alias=True
                )

            except TypeError:
                return result.model_dump()

        return {
            "content": cls._dump_value(
                getattr(
                    result,
                    "content",
                    [],
                )
            ),
            "structuredContent": cls._dump_value(
                getattr(
                    result,
                    "structured_content",
                    None,
                )
            ),
            "isError": bool(
                getattr(
                    result,
                    "is_error",
                    False,
                )
            ),
            "_meta": cls._dump_value(
                getattr(
                    result,
                    "meta",
                    None,
                )
            ),
        }

    @classmethod
    def _dump_value(
        cls,
        value: Any,
    ) -> Any:

        if hasattr(
            value,
            "model_dump",
        ):
            try:
                return value.model_dump(
                    by_alias=True
                )

            except TypeError:
                return value.model_dump()

        if isinstance(
            value,
            list,
        ):
            return [
                cls._dump_value(
                    item
                )
                for item in value
            ]

        if isinstance(
            value,
            dict,
        ):
            return {
                key: cls._dump_value(
                    item
                )
                for key, item
                in value.items()
            }

        return value

import json

import httpx

from lfx.custom.custom_component.component import Component
from lfx.io import (
    DataInput,
    IntInput,
    Output,
    SecretStrInput,
    StrInput,
)
from lfx.schema.data import Data


class WebappReviewPOST(Component):
    display_name = "Webapp Review POST"
    description = (
        "POSTs the HITL review payload to the webapp "
        "for human review."
    )
    icon = "send"
    name = "WebappReviewPOST"

    inputs = [
        DataInput(
            name="review_payload",
            display_name="Review Payload",
            required=True,
        ),
        StrInput(
            name="endpoint_url",
            display_name="Webapp Endpoint URL",
            info="Example: https://your-app.com/api/email-reviews",
            required=True,
        ),
        SecretStrInput(
            name="api_key",
            display_name="API Key",
            info="Optional API key for the webapp endpoint.",
            required=False,
        ),
        StrInput(
            name="api_key_header",
            display_name="API Key Header",
            value="Authorization",
            advanced=True,
        ),
        StrInput(
            name="api_key_prefix",
            display_name="API Key Prefix",
            value="Bearer",
            advanced=True,
        ),
        StrInput(
            name="extra_headers",
            display_name="Extra Headers",
            info='Optional JSON object. Example: {"x-source": "langflow"}',
            value="{}",
            advanced=True,
        ),
        IntInput(
            name="timeout",
            display_name="Timeout",
            value=30,
            advanced=True,
        ),
    ]

    outputs = [
        Output(
            name="response",
            display_name="Webapp Response",
            method="send_review",
        ),
    ]

    @staticmethod
    def _as_dict(value):
        if isinstance(value, Data):
            value = value.data

        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError:
                return {}

        return value if isinstance(value, dict) else {}

    @staticmethod
    def _secret_value(value):
        if value is None:
            return ""

        if hasattr(value, "get_secret_value"):
            return value.get_secret_value().strip()

        return str(value).strip()

    def _build_headers(self):
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
        }

        api_key = self._secret_value(
            self.api_key
        )

        if api_key:
            header_name = str(
                self.api_key_header or "Authorization"
            ).strip()

            prefix = str(
                self.api_key_prefix or ""
            ).strip()

            if prefix:
                headers[header_name] = (
                    f"{prefix} {api_key}"
                )
            else:
                headers[header_name] = api_key

        extra_headers_raw = str(
            self.extra_headers or "{}"
        ).strip()

        if extra_headers_raw:
            try:
                extra_headers = json.loads(
                    extra_headers_raw
                )
            except json.JSONDecodeError as exc:
                raise ValueError(
                    "EXTRA_HEADERS_INVALID: "
                    "Extra Headers must be valid JSON."
                ) from exc

            if not isinstance(extra_headers, dict):
                raise ValueError(
                    "EXTRA_HEADERS_INVALID: "
                    "Extra Headers must be a JSON object."
                )

            for key, value in extra_headers.items():
                headers[str(key)] = str(value)

        return headers

    async def send_review(self) -> Data:
        payload = self._as_dict(
            self.review_payload
        )

        if not payload:
            raise ValueError(
                "REVIEW_PAYLOAD_INVALID: "
                "Review Payload is required."
            )

        endpoint = str(
            self.endpoint_url or ""
        ).strip()

        if not endpoint:
            raise ValueError(
                "WEBAPP_ENDPOINT_INVALID: "
                "Webapp Endpoint URL is required."
            )

        headers = self._build_headers()

        try:
            async with httpx.AsyncClient(
                timeout=float(self.timeout or 30)
            ) as client:

                response = await client.post(
                    endpoint,
                    json=payload,
                    headers=headers,
                )

        except httpx.RequestError as exc:
            raise ValueError(
                "WEBAPP_REQUEST_FAILED: "
                f"{str(exc)}"
            ) from exc

        response_text = (
            response.text or ""
        ).strip()

        try:
            response_body = (
                response.json()
                if response_text
                else {}
            )
        except Exception:
            response_body = response_text

        if not 200 <= response.status_code < 300:
            raise ValueError(
                "WEBAPP_POST_FAILED: "
                f"HTTP {response.status_code} - "
                f"{response_text}"
            )

        self.status = (
            f"REVIEW_SUBMITTED | "
            f"HTTP {response.status_code}"
        )

        return Data(
            data={
                "success": True,
                "status_code": response.status_code,
                "response": response_body,
                "message_id": payload.get(
                    "message_id"
                ),
                "conversation_id": payload.get(
                    "conversation_id"
                ),
                "review_status": payload.get(
                    "review_status"
                ),
            }
        )
